int main() {
  std::mt19937 e1(42);
  std::cout << e1() << '\n';                       // line 1

  std::mt19937 e2(42);
  std::uniform_int_distribution<int> d(1, 6);
  std::cout << d(e2) << '\n';                      // line 2

  std::mt19937 e3(42);
  std::vector<int> v(10);
  std::iota(v.begin(), v.end(), 0);
  std::shuffle(v.begin(), v.end(), e3);
  std::cout << v[0] << '\n';                       // line 3
}

